#!/usr/bin/env node
// Engine set generator (engine/DESIGN.md section 4): the SET PLAN of an episode and the generated sets.
//   node engine/setgen/plan.mjs --episode t00            the plan: per set reuse | variant | generate | error
//   node engine/setgen/plan.mjs --episode t00 --write    + write the generated sets (make-episode's `sets` stage)
//   node engine/setgen/plan.mjs --episode t00 --check    exit 1 when a generated file would change
// Per set of the shot list (final/shotlist.json) and SET block (final/sets.plan.json, engine/input/shotlist-parse.mjs):
//   reuse     a hand-written registry set (registry.js SETS), no template: as it is (a `tod:` goes into continuity)
//   variant   a hand-written registry set + template / dressing: written as a shotSet-style wrapper <ID>_<EP>
//             (the base builder as-is, the base sheet); dressing words are FLAGGED (bespoke props are manual)
//   generate  a SET block with a template (templates/<name>.mjs): the set is built from the description
//   error     no registry set, no template (or an unknown template)
// Generated files (each with a GENERATED header + an input hash; a hand-edited file is never overwritten):
//   scenes/lib/director/sets/<id>.js           the thin wrapper (PARAMS + the template's builder)
//   scenes/lib/director/sets/sheets/<ID>.json  the set sheet (marks, paths, vantages, solids computed in Node)
//   scenes/lib/director/registry-gen.js        GEN_SETS, spread into registry.js SETS
//   episodes/<ep>/final/continuity.js          the episode's continuity (tod / sun per set and scene)
//   episodes/<ep>/final/sets-report.md         the plan + flags (unmatched feature phrases, notes)
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { pathToFileURL } from 'node:url';
import { dirs, episodeArg, ROOT } from '../../scenes/lib/director/episode-paths.js';
import { describeSet, parseTod } from './describe.mjs';
import { sunDirOf } from '../../scenes/lib/director/sets/gen/interior-room-layout.js';

export const SETGEN_VERSION = 1;
const SETS_DIR = path.join(ROOT, 'scenes/lib/director/sets');
const SHEETS = path.join(SETS_DIR, 'sheets');
const REG_GEN = path.join(ROOT, 'scenes/lib/director/registry-gen.js');
const TEMPLATES = ['interior-room', 'town-square', 'sky-sea'];
const PLANNED = ['harbour', 'coast-stacks', 'field'];
const GEN = 'GENERATED by engine/setgen/plan.mjs';
const rel = (f) => path.relative(ROOT, f).split(path.sep).join('/');
const readJson = (f, d = null) => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch { return d; } };
const sha = (s) => crypto.createHash('sha1').update(s).digest('hex').slice(0, 12);
export const kebab = (id) => id.toLowerCase().replace(/_/g, '-');
const stable = (o) => JSON.stringify(o, (k, v) => (v && typeof v === 'object' && !Array.isArray(v) ? Object.fromEntries(Object.keys(v).sort().map((x) => [x, v[x]])) : v));

/** The registry as it is on disk now (a fresh import: plan.mjs rewrites registry-gen.js). */
async function registry() {
  const f = path.join(ROOT, 'scenes/lib/director/registry.js');
  return import(pathToFileURL(f).href + `?t=${Date.now()}`).then(async (m) => {
    const g = await import(pathToFileURL(REG_GEN).href + `?t=${Date.now()}`);
    // registry.js's own import of registry-gen.js is cached: take the generated part from the fresh copy
    const hand = Object.fromEntries(Object.entries(m.SETS).filter(([k, v]) => !v.generated));
    return { SETS: { ...hand, ...g.GEN_SETS }, HAND: hand, GEN: g.GEN_SETS };
  });
}
const loadTemplate = async (t) => (TEMPLATES.includes(t) ? import(`./templates/${t}.mjs`) : null);

/** Per set: { id, action, template, reason, desc?, flags[], notes[] } */
export async function planSets(ep) {
  const D = dirs(ep);
  const { HAND, GEN } = await registry();
  const shotlist = readJson(D.shotlist, { shots: [] });
  const blocks = readJson(path.join(D.final, 'sets.plan.json'), { sets: [] }).sets;
  const used = [...new Set(shotlist.shots.filter((s) => s.render !== 'black').map((s) => s.set))];
  const ids = [...new Set([...blocks.map((b) => b.id), ...used])];
  const out = [];
  for (const id of ids) {
    const b = blocks.find((x) => x.id === id) || null;
    const r = { id, action: null, template: b?.template || null, reason: '', flags: [], notes: [], block: b, shots: shotlist.shots.filter((s) => s.set === id).map((s) => s.id) };
    const gen = GEN[id];
    if (HAND[id] && !b?.template && !b?.dressing) { r.action = 'reuse'; r.reason = 'a hand-written registry set'; }
    else if (HAND[id]) { r.action = 'variant'; r.reason = `registry set + ${b.template ? 'template' : 'dressing'}: a shotSet-style wrapper ${id}_${ep.toUpperCase()}`; }
    else if (b?.template && TEMPLATES.includes(b.template)) { r.action = 'generate'; r.reason = `template ${b.template}`; }
    else if (b?.template && PLANNED.includes(b.template)) { r.action = 'error'; r.reason = `template ${b.template} is planned (DESIGN.md section 4) but not built yet: use ${TEMPLATES.join(', ')}`; }
    else if (b?.template) { r.action = 'error'; r.reason = `unknown template "${b.template}" (templates: ${TEMPLATES.join(', ')})`; }
    else if (gen) { r.action = 'reuse'; r.reason = `a generated set (${gen.generated?.template}, made for ${gen.generated?.episode})`; }
    else { r.action = 'error'; r.reason = b ? 'not in the registry and the SET block has no template:' : 'not in the registry and no SET block describes it'; }
    if (gen && gen.generated?.episode !== ep && r.action === 'generate') { r.action = 'error'; r.reason = `${id} was generated for ${gen.generated.episode}: another episode reuses it (drop the template: line) or names a new set id`; }
    if (r.action === 'generate' || r.action === 'variant') {
      const tpl = await loadTemplate(b.template);
      r.desc = describeSet(b, tpl);
      for (const u of r.desc.unmatched) r.flags.push(`FLAG unmatched feature "${u}" (not in the ${b.template || 'template'} vocabulary: ${Object.keys(tpl?.VOCAB || {}).join(', ')})`);
    }
    if (!used.includes(id)) r.notes.push('no shot uses it');
    out.push(r);
  }
  return out;
}

/** Writes the generated sets of one episode. Returns { files: Map(path -> text), plan, notes } (written unless check). */
export async function generateSets(ep, { check = false, log = console.log } = {}) {
  const D = dirs(ep);
  const plan = await planSets(ep);
  const { GEN: genSets } = await registry();
  const files = new Map();
  const gen = { ...genSets };
  const cont = { scenes: {}, sets: {} };
  for (const r of plan) {
    if (r.action === 'reuse' && r.block?.tod) {
      // a reused set at another time of day: continuity only (registry.js stays Episode 1's)
      const t = parseTod(r.block.tod);
      if (t?.scene) (cont.sets[r.id] ||= {})[t.scene] = { tod: t.tod || t.text, ...(t.az != null ? { sun: sunDirOf(t.az, Math.max(-2, t.el)) } : {}) };
    }
    if (r.action === 'variant') {
      const vid = `${r.id}_${ep.toUpperCase()}`;
      const base = (await registry()).HAND[r.id];
      const head = `// ${GEN} (variant of ${r.id} for ${ep}) - do not edit: change the SET block and re-run.`;
      files.set(path.join(SETS_DIR, `${kebab(vid)}.js`), `${head}\n// dressing asked for (not built: bespoke props are manual, DESIGN.md section 7): ${r.block.dressing || '-'}\nexport { cinematic, build } from './${base.builder}.js';\n`);
      const bs = readJson(path.join(SHEETS, `${r.id.replace(/_\d+$/, '')}.json`));
      if (bs) files.set(path.join(SHEETS, `${vid}.json`), JSON.stringify({ ...bs, set: vid, builder: `scenes/lib/director/sets/${kebab(vid)}.js`, generated: `${GEN} (variant of ${r.id}, ${ep})`, specs: [] }, null, 1) + '\n');
      gen[vid] = { file: `${kebab(vid)}.js`, builder: kebab(vid), frame: base.frame, shotSet: r.id, libs: [`sets/${base.builder}.js (its build() as-is)`], from: `${r.id} + dressing (engine/setgen variant, ${ep})`, generated: { by: 'engine/setgen/plan.mjs', template: 'variant', episode: ep }, continuity: {} };
      if (r.block.dressing) r.flags.push(`FLAG dressing "${r.block.dressing}" is not built (the variant renders the base set as-is)`);
    }
    if (r.action !== 'generate') continue;
    const tpl = await loadTemplate(r.template);
    const { P, notes } = tpl.params(r.desc);
    r.notes.push(...notes);
    const file = `${kebab(r.id)}.js`;
    const input = sha(stable({ v: SETGEN_VERSION, t: r.template, desc: { ...r.desc, source_line: null }, P }));
    const head = `// ${GEN} (template ${r.template}, episode ${ep}, input ${input}) - do not edit: change the SET block of\n// episodes/${ep}/input/shotlist.txt and run  node engine/setgen/plan.mjs --episode ${ep} --write\n// ${r.id}: ${(r.block.features || []).join('; ')}`;
    files.set(path.join(SETS_DIR, file), tpl.builderText(r.id, P, head));
    const sheet = await tpl.sheet(r.id, P, { builderRel: `scenes/lib/director/sets/${file}`, generated: `${GEN} (template ${r.template}, input ${input})`, root: ROOT });
    const c = tpl.continuity(r.desc, P);
    const scene = r.desc.tod?.scene || readJson(D.shotlist, { shots: [] }).shots.find((s) => s.set === r.id)?.scene || null;
    if (c && scene) { (cont.sets[r.id] ||= {})[scene] = c; sheet.continuity = { [scene]: { tod: c.tod, sun: c.sun } }; }
    sheet.generated = `${GEN} (template ${r.template}, input ${input}, sheet ${sha(stable({ ...sheet, generated: null }))})`;   // the stager keys shots on it
    files.set(path.join(SHEETS, `${r.id}.json`), JSON.stringify(sheet, null, 1) + '\n');
    gen[r.id] = { file, builder: kebab(r.id), frame: P.world?.frame || sheet.frame || 'LOCAL', libs: tpl.LIBS,
      from: `engine/setgen template ${r.template} from the SET block of episodes/${ep}/input/shotlist.txt`,
      about: `${r.template}: ${(r.block.features || []).join('; ')}`,
      generated: { by: 'engine/setgen/plan.mjs', template: r.template, episode: ep, input },
      ...(P.world ? { world: P.world } : {}),
      // a default light for a page with no episode continuity (the episode's own is in final/continuity.js)
      continuity: c && scene ? { [scene]: { tod: c.tod, ...(c.sun ? { sun: c.sun } : { sun: null }), exposure: c.exposure, ...(c.lamps != null ? { lamps: c.lamps } : {}) } } : {} };
  }
  // registry-gen.js: every generated set (this episode's replaced, other episodes' kept)
  const ids = Object.keys(gen).sort();
  files.set(REG_GEN, `// ${GEN} - do not edit (re-run: node engine/setgen/plan.mjs --episode <ep> --write).\n// Sets made by the engine's set generator from a shot list's SET block (engine/DESIGN.md section 4), spread\n// into registry.js SETS. Continuity (sun, time of day) is per episode: episodes/<ep>/final/continuity.js.\nexport const GEN_SETS = {${ids.length ? '\n' + ids.map((k) => `  ${k}: ${JSON.stringify(gen[k])},`).join('\n') + '\n' : ''}};\n`);
  if (Object.keys(cont.sets).length || Object.keys(cont.scenes).length || fs.existsSync(path.join(D.final, 'continuity.js'))) {
    files.set(path.join(D.final, 'continuity.js'), `// ${GEN} - the per-episode continuity of ${ep} (engine/DESIGN.md section 4): read by the scene files\n// (staging/set-scene.js createSetScene({ ..., continuity })) and build-shots.mjs. From the shot list's SET blocks (tod:).\nexport default ${JSON.stringify(cont, null, 1)};\n`);
  }
  const md = [`# Set plan - ${ep}`, '', `Generated by \`engine/setgen/plan.mjs\`. FLAG = look at it (an unmatched feature phrase is never guessed).`, '',
    '| set | action | template | shots | why | flags / notes |', '|---|---|---|---|---|---|',
    ...plan.map((r) => `| ${r.id} | ${r.action} | ${r.template || '-'} | ${r.shots.join(' ') || '-'} | ${r.reason} | ${[...r.flags, ...r.notes].join('; ').replace(/\|/g, '/') || '-'} |`)];
  files.set(path.join(D.final, 'sets-report.md'), md.join('\n') + '\n');
  let changed = 0;
  for (const [f, text] of files) {
    const old = fs.existsSync(f) ? fs.readFileSync(f, 'utf8') : null;
    if (old === text) continue;
    if (old != null && !old.includes(GEN) && !f.endsWith('.json') && !f.endsWith('.md')) throw new Error(`${rel(f)} is hand-written: refusing to overwrite it`);
    if (old != null && f.endsWith('.json') && !String(readJson(f)?.generated || '').includes(GEN)) throw new Error(`${rel(f)} is not a generated sheet: refusing to overwrite it`);
    changed++;
    if (check) { log(`out of date: ${rel(f)}`); continue; }
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.writeFileSync(f, text);
    log(`wrote ${rel(f)}`);
  }
  return { files, plan, changed };
}

async function main() {
  const { ep, argv } = episodeArg(process.argv.slice(2), null);
  if (!ep) throw new Error('--episode <id> is required (e.g. t00)');
  if (ep === 's01e01') throw new Error('s01e01 sets are hand-built (registry.js): nothing to generate');
  const plan = await planSets(ep);
  for (const r of plan) console.log(`${r.id.padEnd(22)} ${r.action.padEnd(8)} ${r.reason}${r.flags.length ? `\n${r.flags.map((f) => `    ${f}`).join('\n')}` : ''}`);
  const bad = plan.filter((r) => r.action === 'error');
  if (argv.includes('--write') || argv.includes('--check')) {
    const { changed } = await generateSets(ep, { check: argv.includes('--check') });
    if (argv.includes('--check') && changed) process.exit(1);
  }
  if (bad.length) process.exit(1);
}
if (import.meta.url === pathToFileURL(process.argv[1] || '').href) main().catch((e) => { console.error(e.message || e); process.exit(1); });
